"use strict";

import React, { useState } from "react";

/**
 * =====================================================
 * SIGNUP AGREE PAGE
 * 회원가입 전 약관동의 페이지
 * 기존 API / 회원가입 로직 변경 없음
 * 동의 완료 후 /signup 이동
 * 전체동의 / 필수동의 / 선택동의 지원
 * 관리자 약관관리 localStorage 내용 상세보기 연결
 * =====================================================
 */

const GOLD_LIGHT = "#F7D774";
const GOLD = "#D4AF37";
const GOLD_DARK = "#B8860B";
const GOLD_GRADIENT = `linear-gradient(90deg, ${GOLD_LIGHT} 0%, ${GOLD} 55%, ${GOLD_DARK} 100%)`;
const SOFT_GOLD_GRADIENT =
  "linear-gradient(90deg, rgba(247, 215, 116, 0.075) 0%, rgba(212, 175, 55, 0.06) 55%, rgba(184, 134, 11, 0.075) 100%)";

const SIGNUP_AGREE_REFERENCE_IMAGE =
  "data:image/png;base64,";

function SignupAgreePage({ navigate }) {
  const [agreements, setAgreements] = useState({
    service: false,
    privacy: false,
    privacyRequired: false,
    privacyOptional: false,
    location: false,
    age: false,
    keepAccount: false,
  });

  const go = (path) => {
    try {
      if (typeof navigate === "function") {
        navigate(path);
        return;
      }

      window.history.pushState({}, "", path);
      window.dispatchEvent(new PopStateEvent("popstate"));
    } catch {
      window.location.href = path;
    }
  };

  const requiredChecked =
    agreements.service &&
    agreements.privacy &&
    agreements.privacyRequired &&
    agreements.age;

  const allChecked =
    agreements.service &&
    agreements.privacy &&
    agreements.privacyRequired &&
    agreements.privacyOptional &&
    agreements.location &&
    agreements.age &&
    agreements.keepAccount;

  const toggleAll = () => {
    const next = !allChecked;

    setAgreements({
      service: next,
      privacy: next,
      privacyRequired: next,
      privacyOptional: next,
      location: next,
      age: next,
      keepAccount: next,
    });
  };

  const toggleOne = (key) => {
    setAgreements((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  const openTerms = (type) => {
    go(`/terms?type=${encodeURIComponent(type)}`);
  };

  const handleNext = () => {
    if (!requiredChecked) {
      alert("필수 약관에 모두 동의해주세요.");
      return;
    }

    try {
      sessionStorage.setItem("signupAgreeChecked", "true");
    } catch (e) {
      console.warn("SIGNUP AGREE SAVE FAIL");
    }

    go("/signup");
  };

  return (
    <div style={container}>
      <div style={referenceStage}>
        <img
          src={SIGNUP_AGREE_REFERENCE_IMAGE}
          alt="NORA 개인 회원가입 약관동의"
          style={referenceImage}
          draggable={false}
        />

        <div style={card}>
          <div style={titleWrap}>
            <h2 style={title}>개인 회원가입 약관동의</h2>
            <div style={titleLine} />
          </div>

          <p style={desc}>
            노라 서비스 이용을 위해 아래 약관에 동의해주세요.
          </p>

          <button
            type="button"
            onClick={toggleAll}
            style={allButton}
            aria-pressed={allChecked}
          >
            <span
              style={{
                ...allCheckIcon,
                ...(allChecked ? allCheckIconActive : null),
              }}
            >
              {allChecked ? "✓" : ""}
            </span>

            <span>{allChecked ? "전체동의 해제" : "전체동의"}</span>
          </button>

          <div style={agreementList}>
            <AgreementRow
              checked={agreements.service}
              onCheck={() => toggleOne("service")}
              title="서비스 이용약관 (필수)"
              onView={() => openTerms("service")}
              showView
            />

            <AgreementRow
              checked={agreements.privacy}
              onCheck={() => toggleOne("privacy")}
              title="개인정보 처리방침 (필수)"
              onView={() => openTerms("privacy")}
              showView
            />

            <AgreementRow
              checked={agreements.privacyRequired}
              onCheck={() => toggleOne("privacyRequired")}
              title="개인정보 수집 및 이용동의 (필수)"
              onView={() => openTerms("privacyRequired")}
              showView
            />

            <AgreementRow
              checked={agreements.privacyOptional}
              onCheck={() => toggleOne("privacyOptional")}
              title="개인정보 수집 및 이용동의 (선택)"
              onView={() => openTerms("privacyOptional")}
              showView
            />

            <AgreementRow
              checked={agreements.location}
              onCheck={() => toggleOne("location")}
              title="위치기반서비스 이용약관 (선택)"
              onView={() => openTerms("location")}
              showView
            />

            <AgreementRow
              checked={agreements.age}
              onCheck={() => toggleOne("age")}
              title="14세 이상입니다. (필수)"
            />

            <AgreementRow
              checked={agreements.keepAccount}
              onCheck={() => toggleOne("keepAccount")}
              title="장기미사용시에도 계정유지 (선택)"
            />
          </div>

          <button
            type="button"
            style={{
              ...nextButton,
              ...(!requiredChecked ? nextButtonDisabled : null),
            }}
            onClick={handleNext}
            disabled={!requiredChecked}
          >
            다음　→
          </button>

          <button
            type="button"
            style={backButton}
            onClick={() => go("/login")}
          >
            로그인으로 돌아가기
          </button>
        </div>
      </div>
    </div>
  );
}

function AgreementRow({
  checked,
  onCheck,
  title,
  onView,
  showView = false,
}) {
  return (
    <div
      style={{
        ...agreeBox,
        ...(checked ? agreeBoxChecked : null),
      }}
    >
      <button
        type="button"
        onClick={onCheck}
        style={checkRow}
        aria-pressed={checked}
      >
        <span
          style={{
            ...checkIcon,
            ...(checked ? checkIconActive : null),
          }}
        >
          {checked ? "✓" : ""}
        </span>

        <span style={agreeTitle}>{title}</span>
      </button>

      {showView && (
        <button
          type="button"
          onClick={onView}
          style={viewButton}
        >
          클릭
        </button>
      )}
    </div>
  );
}

